class Solution {
public:
    int stoneGameVII(vector<int>& stones) {
        int n = stones.size();
        vector<int> p(n + 1, 0);
        for (int i = 0; i < n; i++) p[i + 1] = p[i] + stones[i];
        vector<int> dp(n, 0);
        for (int L = 2; L <= n; L++) {
            int prev = dp[n - L + 1];
            for (int i = n - L; i >= 0; i--) {
                int old = dp[i];
                int sumLeft  = p[i + L] - p[i + 1];   // sum(i+1, i+L-1)
                int sumRight = p[i + L - 1] - p[i];   // sum(i,   i+L-2)
                dp[i] = max(sumLeft - prev, sumRight - old);
                prev = old;
            }
        }
        return dp[0];
    }
};
